<script setup>
import { computed,inject,ref } from 'vue';
import {useRoute} from 'vue-router';
import {requestBranchBills} from '../../../api/cc-report-bills';
import {watchVisibleReport} from '../../../lib/cc-visible-report';
import {branchOf,visitStatus,downloadCsv} from '../../../lib/cc';
import { agentReportKey } from '../../../lib/cc-agent-report-context';
import CCDataTable from '../CCDataTable.vue';
import CCPager from '../CCPager.vue';
import CCBranchSummaryCards from './CCBranchSummaryCards.vue';
import CCVisitDetailsDialog from './CCVisitDetailsDialog.vue';
const { ownerNames, financial, refreshKey, from, to, branch, agent, status, search, sort, rows, page, loading, error, truncated, applied, columns, branches, agents, statuses, filtered, visible, pages, cards, grouping, hidden, rolling, rollingBusy, rollingError, toggleSection, summaryGroups, summaryOrder, openDrill, openLead, loadRolling, exportRows } = inject(agentReportKey);
const walkinLead=ref(null);
const route=useRoute(),billData=ref({}),billBusy=ref(false),billError=ref(''),billDetail=ref(null);
const bookedIds=computed(()=>visible.value.filter(row=>visitStatus(row)==='Visited-BKD').map(row=>row.name));
const reportColumns=computed(()=>[{key:'idx',label:'#',value:row=>filtered.value.indexOf(row)+1},{key:'branch',label:'Branch',value:branchOf},{key:'lead_name',label:'Client'},{key:'lead_owner',label:'CC Agent',value:row=>ownerNames.value[row.lead_owner]||row.lead_owner},{key:'date',label:'Date',value:row=>String(row.custom_appointment_date_and_time||'').slice(0,10)},{key:'time',label:'Time',value:row=>String(row.custom_appointment_date_and_time||'').slice(11,16)},{key:'lifeVisit',label:'Visit',value:row=>Number.isFinite(row.lifeVisit)?'V'+row.lifeVisit:'Not verified'},{key:'status',label:'Status',value:visitStatus},{key:'bill_paid',label:'Bill Paid',value:row=>billText(row)}]);
function billText(row){if(visitStatus(row)!=='Visited-BKD')return '—';if(!Object.hasOwn(billData.value,row.name))return billBusy.value?'Checking…':'Not verified';const item=billData.value[row.name];return !item?'Not verified':Number(item.paid)>0?'₹'+Number(item.paid).toLocaleString('en-IN'):item.has_bill?'₹0 · Unpaid':'⚠ ₹0 · No bill yet';}
let previousRefresh;
async function loadBills(){if(!bookedIds.value.length)return;const refresh=previousRefresh!==undefined&&previousRefresh!==refreshKey.value;previousRefresh=refreshKey.value;billBusy.value=true;billError.value='';try{Object.assign(billData.value,await requestBranchBills(bookedIds.value,refresh));}catch(e){billError.value=e.message;}finally{billBusy.value=false;}}
watchVisibleReport(()=>[bookedIds.value.join('|'),refreshKey.value],()=>route.meta.reportTab==='visits',loadBills,()=>bookedIds.value.every(id=>Object.hasOwn(billData.value,id)));
async function exportSchedule(){billBusy.value=true;try{const ids=filtered.value.filter(row=>visitStatus(row)==='Visited-BKD').map(row=>row.name);Object.assign(billData.value,await requestBranchBills(ids));downloadCsv('cc-branch-visits.csv',reportColumns.value,filtered.value);}catch(e){billError.value=e.message;}finally{billBusy.value=false;}}
</script>
<template><section class="cc-branch-visits-page">  <div  class="cc-filters"><label>Branch<select v-model="branch"><option value="">All returned branches</option><option v-for="b in branches" :key="b">{{b}}</option></select></label><label>Agent<select v-model="agent"><option value="">All returned agents</option><option v-for="a in agents" :key="a">{{ownerNames[a]||a}}</option></select></label><label>Status<select v-model="status"><option value="">All statuses</option><option v-for="s in statuses" :key="s">{{s}}</option></select></label><label>Search<input v-model="search" type="search" placeholder="Client, Lead ID, branch or agent"></label><label>Sort<select v-model="sort"><option value="date">Appointment date</option><option value="branch">Branch</option></select></label><button :disabled="loading||!applied||truncated||!filtered.length" @click="exportSchedule">Export filtered CSV</button></div>
  <template v-if="true"><CCBranchSummaryCards v-if="applied"/><div v-if="applied&&!hidden.includes('cards')" class="cc-cards"><button v-for="card in cards" :key="card.name" :aria-pressed="branch===card.name" @click="branch=card.name"><strong>{{card.name||'All returned branches'}}</strong><span>Appointments: {{card.appointments}}</span><span>Visits: {{card.visits}}</span><span>Booked: {{card.booked}}</span><span>Branch pending: {{card.pending}}</span><small v-if="card.overdue">{{card.overdue}} visit updates overdue</small></button></div><p class="cc-note">Pending includes visited outcomes still pending and past appointments awaiting a branch update. Dates and overdue checks use India time. CSV includes every filtered row with masked phone numbers.</p><section v-if="applied&&!hidden.includes('summary')" class="cc-report-summary"><header><h2>{{grouping==='branch'?'Branch-wise':'CC Agent-wise'}} summary</h2><div><button @click="grouping='branch'" :aria-pressed="grouping==='branch'">Branch-wise</button><button @click="grouping='agent'" :aria-pressed="grouping==='agent'">CC Agent-wise</button><button @click="toggleSection('summary')">Hide summary</button></div></header><div class="cc-table"><table><thead><tr><th v-for="[key,label] in [['key',grouping==='branch'?'Branch':'Agent'],['appointments','Appointments'],['visits','Visits'],['booked','Booked'],['notBooked','Not booked'],['pending','Pending'],['noShow','Not visited'],['cancelled','Cancelled'],['showup','Show-up %'],['conversion','Booking %']]" :key="key"><button @click="summaryOrder(key)">{{label}}</button></th></tr></thead><tbody><tr v-for="row in summaryGroups" :key="row.key"><th>{{row.key}}</th><td v-for="key in ['appointments','visits','booked','notBooked','pending','noShow','cancelled']" :key="key"><button @click="openDrill(row.key,key)">{{row[key]}}</button></td><td>{{row.showup}}%</td><td>{{row.conversion}}%</td></tr></tbody></table></div></section>
  <section class="cc-report-summary"><header><h2>Last three business months · conversion</h2><button :disabled="rollingBusy||!applied" @click="loadRolling">{{rollingBusy?'Loading…':'Load comparison'}}</button></header><p v-if="rollingError" role="alert" class="cc-error">{{rollingError}}</p><div v-if="rolling" class="cc-cards"><article v-for="item in rolling" :key="item.from"><strong>{{item.from}} → {{item.to}}</strong><p>{{item.appointments}} appointments · {{item.visits}} visits · {{item.booked}} booked</p><p>Show-up {{item.appointments?Math.round(item.visits*100/item.appointments):0}}% · Booking {{item.visits?Math.round(item.booked*100/item.visits):0}}%</p><span v-if="item.partial" class="cc-error">Partial totals</span></article></div></section>
  <p v-if="billError" role="alert" class="cc-error">Bill details: {{billError}} <button @click="loadBills">Retry bill lookup</button></p><CCDataTable :columns="reportColumns" :rows="visible" :busy="loading"><template #cell-bill_paid="{row}"><button v-if="billData[row.name]?.invoices?.length" @click="billDetail=billData[row.name]">{{billText(row)}}</button><span v-else>{{billText(row)}}</span></template><template #actions="{row}"><button @click="openLead(row.name)">Open lead</button><button @click="walkinLead=row">PD Forms / visit history</button></template></CCDataTable><CCPager :page="page" :pages="pages" :busy="loading" @change="page=$event" /></template><dialog :open="!!billDetail" class="cc-report-dialog cc-bill-dialog"><header><h2>Branch bill payments · client record</h2><button @click="billDetail=null">Close</button></header><CCDataTable :columns="[{key:'invoice',label:'Invoice'},{key:'invoice_date',label:'Invoice Date'},{key:'billed',label:'Billed'},{key:'paid',label:'Paid'},{key:'balance',label:'Balance'}]" :rows="billDetail?.invoices||[]"/></dialog><CCVisitDetailsDialog v-if="walkinLead" :lead="walkinLead" @close="walkinLead=null"/></section></template>
<style scoped src="../../../styles/cc-agent-report.css"></style>

<style scoped>.cc-bill-dialog{position:fixed;inset:10vh auto auto 50%;transform:translateX(-50%);z-index:1000;box-shadow:0 0 0 100vmax #102c2266}</style>
